/* R1085: compact immutable equipment identity and ranked debtor information. */
(()=>{'use strict';
const q=s=>document.querySelector(s),h=v=>esc(String(v??''));
function editor(){const x=(data?.items||[]).find(x=>String(x.id)===String(editingItemId));if(!x)return;const box=q('#rentalItemEditorBox');let identity=box.querySelector('.pbR1085ItemIdentity');if(!identity){identity=document.createElement('div');identity.className='pbR1085ItemIdentity';q('#itemForm').before(identity)}identity.textContent=[categoryLabel(x.category),x.brand,x.model||x.title].filter(Boolean).join(' · ');}
const edit=window.editItem;window.editItem=function(...args){const out=edit.apply(this,args);editor();return out};editItem=window.editItem;
function debtors(){const root=q('#accounting');if(!root)return;let pane=root.querySelector('[data-pb842-pane=debtors]');if(!pane){pane=document.createElement('div');pane.className='pb842SubPane pbR1085Debtors';pane.dataset.pb842Pane='debtors';(root.querySelector('.pb856FinanceShell')||root).appendChild(pane)}const rows=[...(accountingData?.balances||[])].filter(x=>Number(x.balance)>0).sort((a,b)=>Number(b.balance)-Number(a.balance)||String(a.name||'').localeCompare(String(b.name||''),'fa'));const total=rows.reduce((sum,x)=>sum+Number(x.balance),0);pane.innerHTML=`<div class="pbR1085DebtTotal"><span>کل مانده بدهی عکاس‌ها</span><b>${money(total)}</b></div><div class="tableWrap"><table class="accountingTable"><thead><tr><th>عکاس</th><th>کل مبلغ بدهی</th><th>دریافتی</th><th>مانده بدهی</th><th>آخرین پرداخت</th><th>پیامک تسویه</th></tr></thead><tbody>${rows.length?rows.map(x=>`<tr><td><b>${h(x.name||x.mobile||'عکاس')}</b><small dir="ltr">${h(x.mobile||'')}</small></td><td>${money(x.debit_total)}</td><td>${money(x.paid_total)}</td><td><b>${money(x.balance)}</b></td><td>${x.last_payment_at?dateFa(x.last_payment_at):'بدون پرداخت'}</td><td><button class="btn secondary" type="button" data-settlement-sms="${h(x.user_id)}">ارسال پیامک</button></td></tr>`).join(''):'<tr><td colspan="6">عکاسی با مانده بدهی وجود ندارد.</td></tr>'}</tbody></table></div><div role="status" data-debt-msg></div>`;
pane.querySelectorAll('[data-settlement-sms]').forEach(button=>button.onclick=async()=>{const x=rows.find(x=>String(x.user_id)===button.dataset.settlementSms);if(!x)return;if(!await pb920Confirm(`یادآوری تسویه ${money(x.balance)} برای ${x.name||x.mobile} ارسال شود؟ هزینه پیامک از اعتبار فروشگاه کسر می‌شود.`))return;button.disabled=true;const msg=pane.querySelector('[data-debt-msg]');try{await api('/api/rental/accounting/settlement-sms',{method:'POST',body:JSON.stringify({photographerId:x.user_id})});msg.textContent='پیامک یادآوری تسویه ارسال شد.';}catch(e){msg.textContent=({service_wallet_insufficient:'اعتبار پیامکی فروشگاه کافی نیست.',sms_notifications_disabled:'پیامک فروشگاه غیرفعال است.',accounting_debtor_not_found:'این عکاس دیگر مانده بدهی ندارد.',sms_not_configured:'سرویس پیامک آماده نیست.'})[e.error]||'ارسال پیامک انجام نشد. دوباره تلاش کنید.';}finally{button.disabled=false}});
}
const render=renderAccounting;renderAccounting=function(...args){const out=render.apply(this,args);debtors();return out};
debtors();
})();
